"""Literal progressbar markup/CSS; deterministic source measurement diagnostics only."""
from pathlib import Path
import re
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
j=(r/'docs/replica/source/original.js').read_text()
literal=re.search(r'<div class="meter".*?</div></div>',next(x for x in j.splitlines() if x.startswith('function running()'))).group()
(o/'progressmeter-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
script='''const cases=[],rows=[];for(const lang of ['ko','en'])for(const width of [326,656,926])for(const [done,total]of [[0,50],[1,50],[25,50],[50,50],[0,0]]){const t=(ko,en)=>lang==='ko'?ko:en,s={done,total},item=document.createElement('div');item.style.cssText='position:absolute;left:30px;top:'+String(30+cases.length*14)+'px;width:'+width+'px';item.innerHTML=`'''+literal+'''`;document.querySelector('#fixtures').append(item);cases.push({id:lang+'-'+width+'-'+done+'-'+total,lang,width,done,total});}
function read(){return cases.map((c,i)=>{const n=document.querySelector('#fixtures').children[i].firstChild,b=n.getBoundingClientRect(),bar=n.firstChild,css=getComputedStyle(n),bc=getComputedStyle(bar);return{...c,height:b.height,barWidth:bar.getBoundingClientRect().width,background:css.backgroundColor,barBackground:bc.backgroundColor,radius:css.borderRadius,overflow:css.overflow,origin:bc.transformOrigin,transition:bc.transition,label:n.getAttribute('aria-label'),minimum:Number(n.getAttribute('aria-valuemin')),maximum:Number(n.getAttribute('aria-valuemax')),value:Number(n.getAttribute('aria-valuenow')),focusable:n.tabIndex>=0}})}
const frame=()=>new Promise(requestAnimationFrame);
async function timing(){const rows=[],n=document.querySelector('#fixtures').children[0].firstChild,bar=n.firstChild;async function initial(value){bar.style.transition='none';bar.style.transform='scaleX('+value+')';getComputedStyle(bar).transform;await frame();bar.style.transition='';getComputedStyle(bar).transform;await frame();}async function transition(value){bar.style.transform='scaleX('+value+')';getComputedStyle(bar).transform;await frame();const a=bar.getAnimations()[0];if(!a)throw Error('Original transition absent');a.pause();return a;}function sample(label,a,time){a.currentTime=time;rows.push({label,time,duration:a.effect.getComputedTiming().duration,fraction:new DOMMatrix(getComputedStyle(bar).transform).a});}for(const [from,to,key]of [[0,1,'forward'],[1,0,'reverse']]){await initial(from);const a=await transition(to);for(const t of [0,50,100,150,200])sample(key+'-'+t,a,t);a.cancel();}await initial(0);let a=await transition(1);sample('retarget-before',a,70);a=await transition(.5);for(const t of [0,50,200])sample('retarget-'+t,a,t);a.cancel();await initial(0);a=await transition(1);sample('reversal-before',a,80);a=await transition(0);for(const t of [0,40,80])sample('reversal-'+t,a,t);a.cancel();return rows;}

async function lifecycle(){const rows=[],holder=document.querySelector('#fixtures').children[0],n=holder.firstChild,bar=n.firstChild;function record(label){rows.push({label,processed:Number(n.getAttribute('aria-valuenow')),total:Number(n.getAttribute('aria-valuemax')),fraction:n.isConnected?new DOMMatrix(getComputedStyle(bar).transform).a:null,width:n.isConnected?n.getBoundingClientRect().width:null,name:n.getAttribute('aria-label'),attached:n.isConnected,focusable:n.tabIndex>=0})}record('initial-no-entrance');n.setAttribute('aria-valuenow',50);bar.style.transform='scaleX(1)';getComputedStyle(bar).transform;record('normal-start');await new Promise(r=>setTimeout(r,240));record('normal-end');bar.style.transition='none';n.setAttribute('aria-label','Sample processed checks');n.setAttribute('aria-valuenow',25);bar.style.transform='scaleX(.5)';record('reduced-update-language');holder.style.width='656px';record('resize');n.remove();record('detach');holder.append(n);record('remount-no-entrance');return rows;}
'''
(o/'progressmeter-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="progressmeter-original.css"><div id="fixtures"></div><script>'+script+'</script>')
(o/'progressmeter.html').write_text('''<!doctype html><meta charset="utf-8"><title>ProgressMeter · original isolation</title><button id="progressmeter-record">Record ProgressMeter</button><button id="progressmeter-timing">Measure transitions</button><button id="progressmeter-lifecycle">Run lifecycle</button><iframe src="progressmeter-inner.html" width="1000" height="500"></iframe><script>const f=document.querySelector('iframe');document.querySelector('#progressmeter-lifecycle').onclick=async()=>{const data={dpr:devicePixelRatio,lifecycle:await f.contentWindow.lifecycle()};const reply=await fetch('/evidence/root-progressmeter-'+(new URLSearchParams(location.search).get('os')||'mac')+'-control-ready.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!reply.ok)throw Error('Record failed');document.querySelector('#progressmeter-lifecycle').textContent='Lifecycle recorded';};document.querySelector('#progressmeter-record').onclick=async()=>{const data={dpr:devicePixelRatio,rows:f.contentWindow.read()};const reply=await fetch('/evidence/root-progressmeter-'+(new URLSearchParams(location.search).get('os')||'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!reply.ok)throw Error('Record failed');document.querySelector('#progressmeter-record').textContent='Recorded ProgressMeter';};document.querySelector('#progressmeter-timing').onclick=async()=>{const data={dpr:devicePixelRatio,rows:await f.contentWindow.timing()};const reply=await fetch('/evidence/root-progressmeter-'+(new URLSearchParams(location.search).get('os')||'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!reply.ok)throw Error('Record failed');document.querySelector('#progressmeter-timing').textContent='Measured transitions';};</script>''')
print('30 literal progress endpoints + transition retarget/reversal prepared')
